/* Add the shard reply of a single shard based off the given primary node. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    clusterNode *n = listNodeValue(listFirst(nodes));
    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");

    /* Use slot_info_pairs from the primary only */
    n = clusterNodeGetPrimary(n);

    if (n->slot_info_pairs != NULL) {
        serverAssert((n->slot_info_pairs_count % 2) == 0);
        addReplyArrayLen(c, n->slot_info_pairs_count);
        for (int i = 0; i < n->slot_info_pairs_count; i++) {
            addReplyLongLong(c, (unsigned long)n->slot_info_pairs[i]);
        }
    } else {
        /* If no slot info pair is provided, the node owns no slots */
        addReplyArrayLen(c, 0);
    }

    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, listLength(nodes));
    listIter li;
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *node = listNodeValue(ln);
        int reply_count = 0;
        void *node_replylen = addReplyDeferredLen(c);

        addReplyBulkCString(c, "id");
        addReplyBulkCBuffer(c, node->name, CLUSTER_NAMELEN);
        reply_count++;

        if (node->tcp_port) {
            addReplyBulkCString(c, "port");
            addReplyLongLong(c, node->tcp_port);
            reply_count++;
        }

        if (node->tls_port) {
            addReplyBulkCString(c, "tls-port");
            addReplyLongLong(c, node->tls_port);
            reply_count++;
        }

        char *node_ip = node->ip;
        if (c != NULL) {
            client *ip_client = c;
            if (ip_client->conn->type == NULL && server.current_client != NULL) {
                ip_client = server.current_client;
            }
            if (ip_client->peerid == NULL) {
                char peeridbuf[NET_ADDR_STR_LEN] = {0};
                if (ip_client->flag.unix_socket) {
                    snprintf(peeridbuf, sizeof(peeridbuf), "%s:0", server.unixsocket);
                } else {
                    char addr_ip[CONN_ADDR_STR_LEN];
                    int addr_port = 0;
                    if (connAddr(ip_client->conn, addr_ip, sizeof(addr_ip), &addr_port, 1) >= 0) {
                        if (strchr(addr_ip, ':') != NULL) {
                            snprintf(peeridbuf, sizeof(peeridbuf), "[%s]:%d", addr_ip, addr_port);
                        } else {
                            snprintf(peeridbuf, sizeof(peeridbuf), "%s:%d", addr_ip, addr_port);
                        }
                    }
                }
                ip_client->peerid = sdsnew(peeridbuf);
            }
            char *peerid = getClientPeerId(ip_client);
            if (peerid[0] == '[') {
                if (sdslen(node->announce_client_ipv6) != 0) {
                    node_ip = node->announce_client_ipv6;
                }
            } else {
                if (sdslen(node->announce_client_ipv4) != 0) {
                    node_ip = node->announce_client_ipv4;
                }
            }
        }
        addReplyBulkCString(c, "ip");
        addReplyBulkCString(c, node_ip);
        reply_count++;

        const char *endpoint = node_ip;
        char *hostname = node->hostname;
        switch (server.cluster_preferred_endpoint_type) {
        case CLUSTER_ENDPOINT_TYPE_IP:
            endpoint = node_ip;
            break;
        case CLUSTER_ENDPOINT_TYPE_HOSTNAME:
            if (hostname != NULL && hostname[0] != '\0') {
                endpoint = hostname;
            } else {
                endpoint = "?";
            }
            break;
        case CLUSTER_ENDPOINT_TYPE_UNKNOWN_ENDPOINT:
            endpoint = "";
            break;
        default:
            endpoint = "unknown";
            break;
        }
        addReplyBulkCString(c, "endpoint");
        addReplyBulkCString(c, endpoint);
        reply_count++;

        if (sdslen(hostname) != 0) {
            addReplyBulkCString(c, "hostname");
            addReplyBulkCBuffer(c, hostname, sdslen(hostname));
            reply_count++;
        }

        long long node_offset = node->repl_offset;
        if (node->flags & CLUSTER_NODE_MYSELF) {
            if (nodeIsReplica(node)) {
                node_offset = replicationGetReplicaOffset();
            } else {
                node_offset = server.primary_repl_offset;
            }
        } else {
            node_offset = node->repl_offset;
        }

